248		}
249		target, err = deps.resolveAuth(ctx)
250		if err != nil {
251			return nil, err
252		}
253		if target.token == "" {
254			return nil, errors.New("login completed without an active session")
255		}
256		profile, err := deps.fetchProfile(ctx, target.coreURL, target.token)
