264	func ensureConfigureRepoAccess(ctx context.Context, outW, errW io.Writer, reporter configureAccessReporter, initial *api.EnableRepoResponse, cleanRemote, owner, repo string, deps configureFlowDeps) error {
265		fmt.Fprintf(errW, "✗ Entire has no access to %s/%s\n\n", owner, repo)
266		installURL := strings.TrimSpace(initial.InstallURL)
267		if installURL == "" {
268			installURL = fmt.Sprintf("%s/install?repo=%s%%2F%s", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo))
269		}
270	
271		admin, adminErr := deps.githubAdmin(ctx, owner, repo)
272		if adminErr != nil || !admin {
273			fmt.Fprintln(errW, "  An admin needs to install the GitHub app first.")
274			fmt.Fprintln(errW, "  Send them this link to continue:")
275			fmt.Fprintf(errW, "\n  %s\n", installURL)
276			return NewSilentError(errors.New("GitHub app installation required"))
277		}
278	
279		fmt.Fprintln(outW, "  Install the GitHub app to grant access:")
280		fmt.Fprintf(outW, "  %s\n\n", installURL)
281		if err := deps.openURL(ctx, installURL); err != nil {
282			fmt.Fprintln(outW, "  Open the link above in your browser.")
283		}
284		stop := startSpinner(errW, "Waiting for installation")
285		stopped := false
286		defer func() {
287			if !stopped {
288				stop(false)
289			}
290		}()
291	
292		waitCtx, cancel := context.WithTimeout(ctx, configureAccessWaitTimeout)
293		defer cancel()
294		ticker := time.NewTicker(configureAccessPollInterval)
295		defer ticker.Stop()
296		for {
297			select {
298			case <-waitCtx.Done():
299				return fmt.Errorf("waiting for GitHub app installation: %w", waitCtx.Err())
300			case <-ticker.C:
301				access, err := reporter.ReportEnable(waitCtx, cleanRemote)
302				if err == nil && access.Connected {
303					stop(true)
304					stopped = true
305					fmt.Fprintln(outW, "✓ Access granted")
306					return nil
307				}
308			}
309		}
310	}
