374				Value(&selected),
375		))
376		if err := form.RunWithContext(ctx); err != nil {
377			if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
378				return nil, cancelErr
379			}
380			return nil, NewSilentError(errors.New("configure cancelled"))
381		}
382		chosen := make([]regionChoice, 0, len(selected))
383		for _, host := range selected {
384			if region, ok := byHost[host]; ok {
385				chosen = append(chosen, region)
386			}
387		}
388		return chosen, nil
389	}
