574	// promptConfigureUpstreamAndAgents presents upstream and agents as one
575	// persistent form. Arrow keys stay within the active section; Enter confirms a
576	// section and advances, while shift+tab revisits the previous section.
577	func promptConfigureUpstreamAndAgents(ctx context.Context, errW io.Writer, repoRoot string, placements []coreapi.ResolvedPlacement, jurisdiction, manageRegionsHint string) (coreapi.ResolvedPlacement, []agent.Agent, error) {
578		currentHost := configureCurrentUpstream(ctx, repoRoot)
579		placements = configurePlacementOrder(placements, currentHost, jurisdiction)
580		if len(placements) == 0 {
581			return coreapi.ResolvedPlacement{}, nil, errors.New("no upstreams available")
582		}
583	
584		// configurePlacementOrder puts the configured upstream first, so it is also
585		// the initial selection. If this repo has no Entire upstream yet, it falls
586		// back to the jurisdiction-preferred placement.
587		selectedHost := placements[0].ClusterHost
588		placementByHost := make(map[string]coreapi.ResolvedPlacement, len(placements))
589		for _, placement := range placements {
590			placementByHost[placement.ClusterHost] = placement
591		}
592		upstreamOptions := func() []huh.Option[string] {
593			return configureUpstreamOptions(placements, selectedHost, currentHost)
594		}
595	
596		external.DiscoverAndRegisterAlways(ctx)
597		preselected := configureAgentPreselection(ctx)
598		agentOptions := configureAgentOptions(hookAgentOptions(preselected), preselected)
599		if len(agentOptions) == 0 {
600			return coreapi.ResolvedPlacement{}, nil, errors.New("no agents with hook support available")
601		}
602		selectedAgentNames := make([]string, 0, len(preselected))
603		for _, option := range agentOptions {
604			if _, ok := preselected[types.AgentName(option.Value)]; ok {
605				selectedAgentNames = append(selectedAgentNames, option.Value)
606			}
607		}
608	
609		// huh's footer already documents navigation. Keep field descriptions for
610		// contextual information only, rather than repeating keyboard controls.
611		upstreamDescription := manageRegionsHint
612		upstreamControl := &configureUpstreamField{
613			value:       &selectedHost,
614			committed:   selectedHost,
615			highlighted: selectedHost,
616		}
617		upstreamControl.Select = huh.NewSelect[string]().
618			TitleFunc(func() string {
619				return configureQuestionTitle("Which upstream do you want to use?", upstreamControl.focused)
620			}, &upstreamControl.focused).
621			Description(upstreamDescription).
622			Options(upstreamOptions()...).
623			Height(configureFieldHeight(len(placements), upstreamDescription)).
624			Value(&selectedHost)
625		upstreamControl.refresh = func() {
626			upstreamControl.Select.Options(upstreamOptions()...)
627		}
628	
629		agentControl := &configureAgentField{}
630		agentControl.MultiSelect = huh.NewMultiSelect[string]().
631			TitleFunc(func() string {
632				return configureQuestionTitle("Select the agents you want to use", agentControl.focused)
633			}, &agentControl.focused).
634			Options(agentOptions...).
635			// MultiSelect subtracts its title from an implicit viewport height, so
636			// include exactly one title row to show every option without padding.
637			Height(len(agentOptions) + 1).
638			Validate(func(values []string) error {
639				if len(values) == 0 {
640					return errors.New("select at least one agent")
641				}
642				return nil
643			}).
644			Value(&selectedAgentNames)
645	
646		group := huh.NewGroup(upstreamControl, agentControl)
647		form := newConfigureForm(group)
648		// Separate the form from the shell prompt or preceding onboarding status.
649		fmt.Fprintln(errW)
650		if err := form.RunWithContext(ctx); err != nil {
651			if cancelErr := handleFormCancellation(errW, "Configure", err); cancelErr != nil {
652				return coreapi.ResolvedPlacement{}, nil, cancelErr
653			}
654			return coreapi.ResolvedPlacement{}, nil, NewSilentError(errors.New("configure cancelled"))
655		}
656	
657		chosen, ok := placementByHost[selectedHost]
658		if !ok {
659			return coreapi.ResolvedPlacement{}, nil, errors.New("selected upstream is no longer available")
660		}
661		selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
662		for _, name := range selectedAgentNames {
663			ag, err := agent.Get(types.AgentName(name))
664			if err != nil {
665				return coreapi.ResolvedPlacement{}, nil, fmt.Errorf("load selected agent %q: %w", name, err)
666			}
667			selectedAgents = append(selectedAgents, ag)
668		}
669		return chosen, selectedAgents, nil
670	}
