857	func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
858		ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
859		sort.SliceStable(ordered, func(i, j int) bool {
860			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
861			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
862			if iCurrent != jCurrent {
863				return iCurrent
864			}
865			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
866			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
867			if currentHost == "" && iHome != jHome {
868				return iHome
869			}
870			return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
871		})
872		return ordered
873	}
