901	func configureUseMirror(ctx context.Context, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) error {
902		remotes, err := listGitRemotes(ctx, repoRoot)
903		if err != nil {
904			return err
905		}
906		current := ""
907		if remotes[defaultMirrorRemote] {
908			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
909			if err != nil {
910				return fmt.Errorf("read origin remote URL: %w", err)
911			}
912		}
913		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
914		preserve := defaultMirrorUpstreamRemote
915		// An existing forge alias already preserves direct GitHub access. Avoid
916		// manufacturing another alias, and never preserve an old Entire placement
917		// under the misleading name "upstream".
918		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol == gitremote.ProtocolEntire {
919			preserve = ""
920		}
921		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
922		return applyMirrorRemotePlan(ctx, repoRoot, plan)
923	}
