925	// configureGitChanges returns porcelain status keyed by path. Its values retain
926	// XY so callers can detect whether anything was already staged before the flow.
927	func configureGitChanges(ctx context.Context, repoRoot string) (map[string]string, error) {
928		out, err := gitRunner(ctx, repoRoot, "status", "--porcelain=v1", "--untracked-files=all")
929		if err != nil {
930			return nil, fmt.Errorf("read git status: %w", err)
931		}
932		changes := make(map[string]string)
933		for _, line := range strings.Split(out, "\n") {
934			if len(line) < 4 {
935				continue
936			}
937			path := strings.TrimSpace(line[3:])
938			if arrow := strings.LastIndex(path, " -> "); arrow >= 0 {
939				path = path[arrow+4:]
940			}
941			if path != "" {
942				changes[path] = line[:2]
943			}
944		}
945		return changes, nil
946	}
