948	func newConfigureChanges(before, after map[string]string) []string {
949		paths := make([]string, 0, len(after))
950		for path := range after {
951			if _, existed := before[path]; !existed {
952				paths = append(paths, path)
953			}
954		}
955		sort.Strings(paths)
956		return paths
957	}
