959	func configureSaveAndPush(cmd *cobra.Command, repoRoot, owner, repo string, before map[string]string, generated []string, now func() time.Time) error {
960		outW := cmd.OutOrStdout()
961		if len(generated) == 0 {
962			fmt.Fprintln(outW, "  No new configuration changes to commit.")
963			return nil
964		}
965		if len(before) != 0 {
966			fmt.Fprintln(outW, "  Configuration was saved but not committed because the worktree already had changes.")
967			fmt.Fprintln(outW, "  Review and commit the configuration normally when ready.")
968			return nil
969		}
970	
971		branch, err := gitRunner(cmd.Context(), repoRoot, "branch", "--show-current")
972		if err != nil || branch == "" {
973			return errors.New("cannot save configuration from a detached HEAD")
974		}
975		protected, protectionErr := configureBranchProtected(cmd.Context(), owner, repo, branch)
976		if protectionErr != nil {
977			// Protection discovery is advisory; a rejected direct push still fails
978			// safely at git push.
979			protected = false
980		}
981		choice, err := promptConfigureSave(cmd.Context(), cmd.ErrOrStderr(), branch, protected)
982		if err != nil {
983			return err
984		}
985		if protected && choice == configureSaveDirect {
986			return fmt.Errorf("%s is protected; push to a new branch", branch)
987		}
988		if choice != configureSaveDirect && choice != configureSaveNewBranch {
989			return fmt.Errorf("unknown save choice %q", choice)
990		}
991	
992		pushBranch := branch
993		if choice == configureSaveNewBranch {
994			var err error
995			pushBranch, err = availableConfigureBranch(cmd.Context(), repoRoot, now)
996			if err != nil {
997				return err
998			}
999			if _, err := gitRunner(cmd.Context(), repoRoot, "switch", "-c", pushBranch); err != nil {
1000				return fmt.Errorf("create configuration branch: %w", err)
1001			}
1002		}
1003	
1004		args := []string{"add", "--"}
1005		args = append(args, generated...)
1006		if _, err := gitRunner(cmd.Context(), repoRoot, args...); err != nil {
1007			return fmt.Errorf("stage configuration: %w", err)
1008		}
1009		if _, err := gitRunner(cmd.Context(), repoRoot, "commit", "-m", configureCommitMessage); err != nil {
1010			return fmt.Errorf("commit configuration: %w", err)
1011		}
1012		sha, err := gitRunner(cmd.Context(), repoRoot, "rev-parse", "--short", "HEAD")
1013		if err != nil {
1014			return fmt.Errorf("read configuration commit: %w", err)
1015		}
1016		fmt.Fprintf(outW, "✓ Committed %s · %s\n", configureCommitMessage, sha)
1017		if _, err := gitRunner(cmd.Context(), repoRoot, "push", "-u", defaultMirrorRemote, pushBranch); err != nil {
1018			return fmt.Errorf("push configuration: %w", err)
1019		}
1020		fmt.Fprintf(outW, "✓ Pushed to %s/%s\n", defaultMirrorRemote, pushBranch)
1021		if choice == configureSaveNewBranch {
1022			fmt.Fprintln(outW, "  Open a trail to merge it:")
1023			fmt.Fprintf(outW, "  %s/gh/%s/%s/trails/new?branch=%s\n", configureWebBaseURL(), url.PathEscape(owner), url.PathEscape(repo), url.QueryEscape(pushBranch))
1024		}
1025		return nil
1026	}
1027	
1028	func configureBranchProtected(ctx context.Context, owner, repo, branch string) (bool, error) {
1029		out, err := exec.CommandContext(ctx, "gh", "api", "repos/"+owner+"/"+repo+"/branches/"+url.PathEscape(branch), "--jq", ".protected").Output()
1030		if err != nil {
1031			return false, fmt.Errorf("check GitHub branch protection: %w", err)
1032		}
1033		protected, err := strconv.ParseBool(strings.TrimSpace(string(out)))
1034		if err != nil {
1035			return false, fmt.Errorf("parse GitHub branch protection: %w", err)
1036		}
1037		return protected, nil
1038	}
1039	
1040	func availableConfigureBranch(ctx context.Context, repoRoot string, now func() time.Time) (string, error) {
1041		candidates := []string{configureBranchBase, configureBranchBase + "-" + now().Format("20060102-150405")}
1042		for _, candidate := range candidates {
1043			_, err := gitRunner(ctx, repoRoot, "show-ref", "--verify", "--quiet", "refs/heads/"+candidate)
1044			if err == nil {
1045				continue // branch already exists
1046			}
1047			var exitErr *exec.ExitError
1048			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1049				return candidate, nil // show-ref uses 1 for a missing ref
1050			}
1051			return "", fmt.Errorf("check configuration branch %q: %w", candidate, err)
1052		}
1053		return "", errors.New("could not choose an unused configuration branch name")
1054	}
