func TestConfigureSaveIsSkippedWithoutGeneratedChanges(t *testing.T) {
	cmd := &cobra.Command{}
	var out bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(io.Discard)
	if err := configureSaveAndPush(cmd, t.TempDir(), "owner", "repo", nil, nil, time.Now); err != nil {
